const campaignId = $json.body.campaign_id;
const message = $json.body.message;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof campaignId !== 'string' || !uuidRe.test(campaignId)) {
  throw new Error('campaign_id missing or not a valid UUID: ' + JSON.stringify(campaignId));
}
if (typeof message !== 'string' || !message.trim()) {
  throw new Error('message missing or empty');
}
return [{ json: { campaign_id: campaignId, message: message.trim() } }];

const campaign = $('Get campaign').item.json;
const metricsRows = $('Get campaign metrics').all().map(i => i.json).filter(m => m && m.id);
const recRows = $('Get open recommendations').all().map(i => i.json).filter(r => r && r.id);
const historyRows = $('Get recent chat history').all().map(i => i.json)
  .filter(h => h && h.id)
  .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
  .slice(-20);

const totals = metricsRows.reduce((acc, m) => {
  acc.cost += Number(m.cost || 0);
  acc.conversions += Number(m.conversions || 0);
  acc.conversionsValue += Number(m.conversions_value || 0);
  return acc;
}, { cost: 0, conversions: 0, conversionsValue: 0 });

const historyText = historyRows.length
  ? historyRows.map(h => (h.role === 'user' ? 'Agency' : 'Assistant') + ': ' + h.content).join('\n')
  : '(no prior messages)';

const recsText = recRows.length
  ? recRows.map(r => '- ' + r.type + ': $' + r.dollars_recoverable + ' recoverable').join('\n')
  : 'None currently open.';

return [{
  json: {
    campaignName: campaign.campaign_name,
    status: campaign.status,
    dailyBudgetUsd: campaign.daily_budget_usd,
    totalCost: totals.cost,
    totalConversions: totals.conversions,
    totalConversionsValue: totals.conversionsValue,
    roas: totals.cost > 0 ? totals.conversionsValue / totals.cost : null,
    recommendationsText: recsText,
    historyText,
    userMessage: $('Validate input').item.json.message,
  },
}];

